import{_ as e,o as i,c as t,a2 as l}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"📗 行测 · 行政职业能力测验","description":"","frontmatter":{},"headers":[],"relativePath":"xingce/index.md","filePath":"xingce/index.md"}'),n={name:"xingce/index.md"};function r(s,a,d,o,h,u){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="📗-行测-·-行政职业能力测验" tabindex="-1">📗 行测 · 行政职业能力测验 <a class="header-anchor" href="#📗-行测-·-行政职业能力测验" aria-label="Permalink to &quot;📗 行测 · 行政职业能力测验&quot;">​</a></h1><p>行测是公务员考试的笔试科目之一，考察逻辑思维、语言表达、数理分析和常识储备。</p><h2 id="⏱-考试概况" tabindex="-1">⏱ 考试概况 <a class="header-anchor" href="#⏱-考试概况" aria-label="Permalink to &quot;⏱ 考试概况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>题量</td><td>120-135 题（国考）</td></tr><tr><td>时间</td><td>120 分钟</td></tr><tr><td>分值</td><td>100 分（大部分岗位）</td></tr><tr><td>平均每题时间</td><td>约 55 秒</td></tr></tbody></table><h2 id="📐-五大模块" tabindex="-1">📐 五大模块 <a class="header-anchor" href="#📐-五大模块" aria-label="Permalink to &quot;📐 五大模块&quot;">​</a></h2><h3 id="_1-言语理解与表达" tabindex="-1">1. <a href="./yanyu-lijie">言语理解与表达</a> <a class="header-anchor" href="#_1-言语理解与表达" aria-label="Permalink to &quot;1. [言语理解与表达](./yanyu-lijie)&quot;">​</a></h3><ul><li>阅读理解、逻辑填空、语句表达</li><li>约 40 题，建议用时 30-35 分钟</li></ul><h3 id="_2-数量关系" tabindex="-1">2. <a href="./shuliang-guanxi">数量关系</a> <a class="header-anchor" href="#_2-数量关系" aria-label="Permalink to &quot;2. [数量关系](./shuliang-guanxi)&quot;">​</a></h3><ul><li>数学运算、数字推理</li><li>约 10-15 题，建议用时 10-15 分钟</li></ul><h3 id="_3-判断推理" tabindex="-1">3. <a href="./panduan-tuili">判断推理</a> <a class="header-anchor" href="#_3-判断推理" aria-label="Permalink to &quot;3. [判断推理](./panduan-tuili)&quot;">​</a></h3><ul><li>图形推理、定义判断、类比推理、逻辑判断</li><li>约 35-40 题，建议用时 35 分钟</li></ul><h3 id="_4-资料分析" tabindex="-1">4. <a href="./ziliao-fenxi">资料分析</a> <a class="header-anchor" href="#_4-资料分析" aria-label="Permalink to &quot;4. [资料分析](./ziliao-fenxi)&quot;">​</a></h3><ul><li>图表分析、数据计算、综合判断</li><li>约 20 题，建议用时 25-30 分钟</li></ul><h3 id="_5-常识判断" tabindex="-1">5. <a href="./changshi-panduan">常识判断</a> <a class="header-anchor" href="#_5-常识判断" aria-label="Permalink to &quot;5. [常识判断](./changshi-panduan)&quot;">​</a></h3><ul><li>政治、法律、经济、科技、文史</li><li>约 20 题，建议用时 10 分钟</li></ul><h2 id="🎯-做题顺序建议" tabindex="-1">🎯 做题顺序建议 <a class="header-anchor" href="#🎯-做题顺序建议" aria-label="Permalink to &quot;🎯 做题顺序建议&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>资料分析 → 言语理解 → 判断推理 → 常识判断 → 数量关系</span></span>
<span class="line"><span>（先抓确定性高分，后做耗时题型）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="📝-备考策略" tabindex="-1">📝 备考策略 <a class="header-anchor" href="#📝-备考策略" aria-label="Permalink to &quot;📝 备考策略&quot;">​</a></h2><ol><li><strong>资料分析先突破</strong>：公式固定、提分最快，争取 90%+ 正确率</li><li><strong>言语理解保基本</strong>：阅读量积累是王道，多读多练</li><li><strong>判断推理找规律</strong>：逻辑判断题有固定推理框架</li><li><strong>数量关系不纠结</strong>：10 题做对 6-7 题就是胜利</li><li><strong>常识判断靠积累</strong>：碎片时间刷常识，平时多看新闻</li></ol>`,19)])])}const b=e(n,[["render",r]]);export{p as __pageData,b as default};
